const cache = new Map();                       // URL -> WeakRef<Blob>
const registry = new FinalizationRegistry(url => {
  if (!cache.get(url)?.deref()) cache.delete(url);   // re-check, then delete
});
function get(url, load) {
  const hit = cache.get(url)?.deref();
  if (hit) return hit;                          // promotion held in the local
  const value = load(url);
  cache.set(url, new WeakRef(value));
  registry.register(value, url);
  return value;
}

